#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, count;
    cin >> n >> count;
    vector<int> values(n);
    for (int &value : values) cin >> value;
    sort(values.begin(), values.end());
    if (count == 0) {
        cout << (values[0] > 1 ? 1 : -1) << '\n';
    } else if (count == n || values[count - 1] < values[count]) {
        cout << values[count - 1] << '\n';
    } else {
        cout << -1 << '\n';
    }
}
